"use strict";(globalThis.webpackChunkmanual_sqli||=[]).push([[571],{1325(a){a.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/manual-sqli/docs/intro","label":"M\xf3dulo 1: Introducci\xf3n","docId":"intro","unlisted":false},{"type":"link","href":"/manual-sqli/docs/payload-explicado","label":"M\xf3dulo 2: El payload explicado","docId":"payload-explicado","unlisted":false},{"type":"link","href":"/manual-sqli/docs/laboratorio","label":"M\xf3dulo 3: Preparar DVWA en Kali","docId":"laboratorio","unlisted":false},{"type":"link","href":"/manual-sqli/docs/practica-manual","label":"Pr\xe1ctica 1: Inyecci\xf3n manual","docId":"practica-manual","unlisted":false},{"type":"link","href":"/manual-sqli/docs/sqlmap","label":"Pr\xe1ctica 2: Ataque autom\xe1tico (sqlmap)","docId":"sqlmap","unlisted":false},{"type":"link","href":"/manual-sqli/docs/john","label":"Pr\xe1ctica 3: Romper contrase\xf1as (John)","docId":"john","unlisted":false},{"type":"link","href":"/manual-sqli/docs/practica-login","label":"Pr\xe1ctica 4: Vulnerar un login","docId":"practica-login","unlisted":false},{"type":"link","href":"/manual-sqli/docs/defensas","label":"C\xf3mo prevenirlo (c\xf3digo seguro)","docId":"defensas","unlisted":false}]},"docs":{"defensas":{"id":"defensas","title":"C\xf3mo prevenirlo (c\xf3digo seguro)","description":"La buena noticia es que SQL Injection, aunque es peligrosa, se previene con facilidad si se programa con cuidado. Aqu\xed se compara el c\xf3digo mal hecho (vulnerable) con el c\xf3digo corregido (seguro), para ver exactamente qu\xe9 cambia.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"M\xf3dulo 1: Introducci\xf3n","description":"SQL Injection (inyecci\xf3n SQL) es una de las vulnerabilidades m\xe1s conocidas en las p\xe1ginas web. Permite que un atacante introduzca sus propias \xf3rdenes dentro de las consultas que una aplicaci\xf3n le hace a su base de datos, y de esa forma lea, modifique o robe informaci\xf3n que no deber\xeda estar a su alcance.","sidebar":"tutorialSidebar"},"john":{"id":"john","title":"Pr\xe1ctica 3: Romper contrase\xf1as (John)","description":"En las pr\xe1cticas anteriores se obtuvieron las contrase\xf1as en forma de hash MD5 (cadenas como 5f4dcc3b5aa765d61d8327deb882cf99). Un hash parece seguro, pero si la contrase\xf1a es d\xe9bil se puede recuperar la contrase\xf1a original. Eso se demuestra con John the Ripper, otra herramienta incluida en Kali.","sidebar":"tutorialSidebar"},"laboratorio":{"id":"laboratorio","title":"M\xf3dulo 3: Preparar DVWA en Kali","description":"Para demostrar el ataque se usa DVWA (Damn Vulnerable Web Application), una aplicaci\xf3n web pensada para practicar seguridad. Se instala dentro de Kali Linux, el sistema operativo que incluye las herramientas necesarias.","sidebar":"tutorialSidebar"},"payload-explicado":{"id":"payload-explicado","title":"M\xf3dulo 2: El payload explicado","description":"Este es el ejemplo m\xe1s famoso de SQL Injection. A continuaci\xf3n se explica s\xedmbolo por s\xedmbolo para entender por qu\xe9 funciona.","sidebar":"tutorialSidebar"},"practica-login":{"id":"practica-login","title":"Pr\xe1ctica 4: Vulnerar un login","description":"En las pr\xe1cticas anteriores se us\xf3 DVWA. En esta se demuestra el ataque sobre una aplicaci\xf3n con login y un panel privado, parecida a un sistema real. El objetivo es mostrar algo muy claro para el p\xfablico: sin la inyecci\xf3n no se puede entrar al panel, pero con la inyecci\xf3n se entra sin conocer ninguna contrase\xf1a.","sidebar":"tutorialSidebar"},"practica-manual":{"id":"practica-manual","title":"Pr\xe1ctica 1: Inyecci\xf3n manual","description":"Con DVWA preparada, se entra a la secci\xf3n SQL Injection del men\xfa. Aparece un campo que pide un User ID. Ah\xed se har\xe1n las pruebas, de la m\xe1s simple a la m\xe1s avanzada.","sidebar":"tutorialSidebar"},"resumen-docusaurus":{"id":"resumen-docusaurus","title":"Resumen de la herramienta (Docusaurus)","description":"Este manual fue construido con Docusaurus, por lo que esta secci\xf3n explica qu\xe9 es y por qu\xe9 se eligi\xf3."},"sqlmap":{"id":"sqlmap","title":"Pr\xe1ctica 2: Ataque autom\xe1tico (sqlmap)","description":"sqlmap es la herramienta estrella de Kali Linux para SQL Injection. Con un solo comando detecta la vulnerabilidad, roba la base de datos completa y hasta descifra las contrase\xf1as autom\xe1ticamente. Es la demostraci\xf3n m\xe1s impactante: la pantalla trabaja sola y en segundos aparecen los usuarios con sus contrase\xf1as reales.","sidebar":"tutorialSidebar"}}}}')}}]);